55: export function useVisitNotes(patientUuid: string): UseVisitNotes {
56:   const {
57:     visitNoteConfig: { encounterNoteTextConceptUuid, visitDiagnosesConceptUuid },
58:   } = useConfig<ConfigObject>();
59: 
60:   const customRepresentation =
61:     'custom:(uuid,display,encounterDatetime,patient,obs,' +
62:     'encounterProviders:(uuid,display,' +
63:     'encounterRole:(uuid,display),' +
64:     'provider:(uuid,person:(uuid,display))),' +
65:     'diagnoses';
66:   const encountersApiUrl = `${restBaseUrl}/encounter?patient=${patientUuid}&obs=${visitDiagnosesConceptUuid}&v=${customRepresentation}`;
67: 
68:   const { data, error, isLoading, isValidating, mutate } = useSWR<{ data: EncountersFetchResponse }, Error>(
69:     encountersApiUrl,
70:     openmrsFetch,
71:   );
72: 
73:   const mapNoteProperties = (note: RESTPatientNote, index: number): PatientNote => ({
74:     id: `${index}`,
75:     diagnoses: note.diagnoses
76:       .filter((diagnosis) => !diagnosis.voided)
77:       .map((diagnosisData) => diagnosisData.display)
78:       .filter((val) => val)
79:       .join(', '),
80:     encounterDate: note.encounterDatetime,
81:     encounterNote: note.obs.find((observation) => observation.concept.uuid === encounterNoteTextConceptUuid)?.value,
82:     encounterNoteRecordedAt: note.obs.find((observation) => observation.concept.uuid === encounterNoteTextConceptUuid)
83:       ?.obsDatetime,
84:     encounterProvider: note?.encounterProviders[0]?.provider?.person?.display,
85:     encounterProviderRole: note?.encounterProviders[0]?.encounterRole?.display,
86:   });
87: 
88:   const formattedVisitNotes = data?.data?.results
89:     ?.map(mapNoteProperties)
90:     ?.sort((noteA, noteB) => new Date(noteB.encounterDate).getTime() - new Date(noteA.encounterDate).getTime());
91: 
92:   return {
93:     visitNotes: data ? formattedVisitNotes : null,
94:     error,
95:     isLoading,
96:     isValidating,
97:     mutateVisitNotes: mutate,
98:   };
99: }
